/** Responsive variants generated by scripts/optimize-media.mjs into R2 `opt/`. */
export const VARIANT_WIDTHS = [480, 720, 960, 1600] as const;
export const VARIANT_FORMATS = ["avif", "webp"] as const;

/** Widths actually worth emitting for an original of `orig` px (no upscaling, no duplicates). */
export function variantWidths(orig: number) {
	const out: number[] = [];
	for (const w of VARIANT_WIDTHS) {
		out.push(w);
		if (w >= orig) break;
	}
	return out;
}
export const variantUrl = (key: string, w: number, fmt: string) => `/media/opt/${key}/${w}.${fmt}`;
